//! Checked metadata for resident index generation.
use crate::{NativeTensor, layout::Layout};
use alloc::sync::Arc;
use burn_backend::{DType, Shape};
use d3os_compute::{Error, Result, nvidia::Nvidia};
use d3os_nvidia::compute::{Kernel, range};

/// Positive-step I32 range. Values are generated by the device, not staged.
#[derive(Clone, Debug)]
pub struct RangePlan {
    parameters: [u32; range::PARAMETERS],
}

impl RangePlan {
    pub fn new(values: core::ops::Range<i64>, step: usize) -> Result<Self> {
        if step == 0 {
            return Err(Error::InvalidParameter);
        }
        let distance = (i128::from(values.end) - i128::from(values.start)).max(0) as u128;
        let count = distance.div_ceil(step as u128);
        if count > i32::MAX as u128 {
            return Err(Error::SizeOverflow);
        }
        if count == 0 {
            return Ok(Self { parameters: [0, 0, 1] });
        }
        let first = i32::try_from(values.start).map_err(|_| Error::InvalidParameter)?;
        // A singleton never evaluates the caller's step. Normalize it so even a
        // host-sized step can safely produce the one representable index.
        let step = if count == 1 {
            1
        } else {
            u32::try_from(step).map_err(|_| Error::InvalidParameter)?
        };
        let parameters = [count as u32, first as u32, step];
        range::validate(&parameters).map_err(|_| Error::InvalidParameter)?;
        Ok(Self { parameters })
    }

    pub fn len(&self) -> usize {
        self.parameters[0] as usize
    }

    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }
}

impl NativeTensor {
    pub fn arange(plan: RangePlan) -> Result<Self> {
        let layout = Layout::contiguous(Shape::new([plan.len()]))?;
        if plan.is_empty() {
            return Self::empty(layout.shape().clone(), DType::I32);
        }
        let buffer = Nvidia.produce_words(plan.len(), Kernel::Range, &[], &plan.parameters.map(|p| p as usize))?;
        Ok(Self {
            buffer: Arc::new(buffer),
            layout,
            dtype: DType::I32,
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn lengths_and_representability_use_wide_arithmetic() {
        assert_eq!(RangePlan::new(-7..9, 3).unwrap().parameters, [6, (-7i32) as u32, 3]);
        assert_eq!(RangePlan::new(i64::MIN..i64::MAX, usize::MAX).unwrap_err(), Error::InvalidParameter);
        assert_eq!(RangePlan::new(0..1, usize::MAX).unwrap().parameters, [1, 0, 1]);
        assert!(RangePlan::new(core::ops::Range { start: 9, end: -7 }, 1).unwrap().is_empty());
        assert!(RangePlan::new(0..0, 0).is_err());
        assert!(RangePlan::new(0..i64::MAX, 1).is_err());
        assert!(RangePlan::new(i64::from(i32::MAX)..i64::from(i32::MAX) + 2, 1).is_err());
        assert_eq!(
            RangePlan::new(i64::from(i32::MIN)..i64::from(i32::MAX) + 1, u32::MAX as usize)
                .unwrap()
                .parameters,
            [2, i32::MIN as u32, u32::MAX]
        );
    }
}
